-- 1. Check if speed outliers are primarily 1-segment or short-duration trips
SELECT 
    count(*) AS total_outliers_over_150kmh,
    count(*) FILTER (WHERE segment_count = 1) AS outliers_with_single_segment,
    count(*) FILTER (WHERE elapsed_time_sec <= 10) AS outliers_under_10_seconds,
    round(100.0 * count(*) FILTER (WHERE segment_count = 1 OR elapsed_time_sec <= 10) / count(*), 1) AS pct_explained_by_short_pings
FROM base_trips
WHERE avg_speed_kmh > 150;

-- 2. Check how many incomplete trips were generated by sub-trip splitting
SELECT 
    count(*) AS total_incomplete_trips,
    count(*) FILTER (WHERE unique_trip_id NOT LIKE '%_0') AS created_by_mid_trip_split,
    count(*) FILTER (WHERE segment_count = 1) AS incomplete_single_pings
FROM base_trips
WHERE has_completed_end IS FALSE;

-- 3. Check what travel modes make up the 1-segment trips
SELECT 
    travel_mode,
    count(*) AS single_ping_count,
    round(avg(total_distance_m)::numeric, 1) AS avg_dist_m,
    round(avg(elapsed_time_sec)::numeric, 1) AS avg_elapsed_sec
FROM base_trips
WHERE segment_count = 1
GROUP BY travel_mode
ORDER BY single_ping_count DESC
LIMIT 10;
